pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MaliciousBatcher mal;

    function setUp() public { c = new C(); }

    // We fuzz inputs that decide the observable timestamp and provide a payload
    // that the malicious helper will use to conditionally revert during a storage
    // interaction invoked indirectly by the depositor. The helper is used as the
    // batcherHash address encoded into bytes32 so that an internal write that
    // touches that encoded address can trigger a revert in the mutant ordering.
    function testFuzz_property(uint64 _number, uint64 _timestamp, bytes32 _batcherHash) public {
        // keep inputs wide; ensure depositor address is used by simulating the depositor
        address depositor = c.DEPOSITOR_ACCOUNT();
        // deploy a malicious helper which will revert when invoked with a specific magic value
        // We'll choose magic derived from the fuzzed _batcherHash so fuzzer can find a case
        // where the helper reverts during any external interaction it is asked to perform.
        // The helper itself does not need ether.
        mal = new MaliciousBatcher();

        // If we encode the helper's address into _batcherHash, the contract under test may
        // later cause external interaction with that address in real deployments. For our
        // distinguishing scenario, we rely on the fact that changing assignment order means
        // timestamp is set before/after a failing external action; to trigger the external
        // failure we set _batcherHash to the helper's address packed into bytes32.
        bytes32 helperEncoded = bytes32(uint256(uint160(address(mal))));

        // Let the fuzzer decide whether to use the helper address; keep wide by allowing either
        // the provided _batcherHash or the helper encoding. We pick the helper if the low bit of
        // the provided batcherHash is 1, letting the fuzzer choose an adversarial path.
        bytes32 chosenBatcher = (uint8(bytes1(_batcherHash)) & 1 == 1) ? helperEncoded : _batcherHash;

        // Now call setL1BlockValues as the depositor with fuzzed parameters.
        vm.prank(depositor);
        // The call must succeed on the reference for all inputs. If the mutant triggers a revert
        // during one of the middle assignments (which in mutant happens before timestamp write),
        // timestamp will remain its old value (0), making it differ from _timestamp.
        // We supply other args as simple constants; they are not decisive besides _batcherHash and _timestamp.
        c.setL1BlockValues(_number, _timestamp, 0, bytes32(0), 0, chosenBatcher, 0, 0);

        // Exactly one assertion: the reference always ensures that public getter timestamp() equals
        // the supplied _timestamp for any depositor call; the mutant can violate this for some inputs
        // (specifically when chosenBatcher encodes an address that reverts on an interaction that the
        // mutant performs before writing timestamp). We observe c only via its public getter.
        assertTrue(c.timestamp() == _timestamp);
    }
}

// Minimal malicious helper that will revert in fallback so that any external interaction with it fails.
contract MaliciousBatcher {
    fallback() external payable {
        revert("malicious");
    }
}

