contract InvMutTest is Test {
    C c;
    // The depositor account from the contract under test
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    // Fuzz the deciding values: _number and _timestamp and a selector that will determine whether
    // the adversarial helper should revert on being used as a batcherHash-derived callee.
    function testFuzz_property(uint64 _number, uint64 _timestamp, bytes32 _batcherHashSeed) public {
        // Keep domain wide; no restrictive assumes.

        // Deploy a minimal adversarial callee whose address encodes behavior via initialization
        // We will deploy two small helpers and pick one based on _batcherHashSeed low bit.
        Reverter reverter = new Reverter();
        Noop noop = new Noop();

        // Choose helper address based on low bit of seed so fuzzer can flip decision.
        address chosen = (uint8(_batcherHashSeed[0]) & 1 == 1) ? address(reverter) : address(noop);

        // Craft batcherHash so that, when interpreted by an attacker in a mutated contract that
        // might perform an external call using batcherHash as a callee address, it points to our helper.
        // Place chosen address bytes into batcherHash so mutant that mistakenly uses it can trigger revert.
        bytes32 batcherHash = bytes32(bytes20(chosen));

        // Other arbitrary values for the call
        uint256 _basefee = 0x123;
        bytes32 _hash = keccak256(abi.encodePacked(_number, _timestamp, _basefee));
        uint64 _sequenceNumber = 7;
        uint256 _l1FeeOverhead = 1;
        uint256 _l1FeeScalar = 1;

        // Call as the depositor
        vm.prank(DEPOSITOR);
        bool ok;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call succeeded, the contract's public timestamp() equals the provided _timestamp.
        // This is satisfied by the reference for all inputs; the mutant that assigns timestamp last can be made to revert during a later external interaction
        // leaving timestamp unset or different, so the mutant will fail this assertion for some fuzz inputs where ok == true but timestamp differs,
        // or where the mutant reverts (ok == false) after having not set timestamp.
        if (ok) {
            assertTrue(c.timestamp() == _timestamp);
        } else {
            // If the call reverted on the mutant but not on the reference, the reference still would have set timestamp
            // however we cannot observe that directly on a reverted call; to keep a single assertion as required, we assert that when call reverts,
            // timestamp is either unchanged (0) or equal to _timestamp for the reference; since we must make a single assertTrue that the reference
            // satisfies always and the mutant violates for some input, we instead assert that either the call succeeded and timestamp equals _timestamp,
            // or the call reverted — the reference never reverts for depositor so this branch should be false for the reference.
            // To keep exactly one assertTrue over c's observable behaviour, we assert that either call succeeded and timestamp matches.
            // Here we assert false so that for reference (which will have ok==true) the test passes; for mutant some inputs will cause ok==false and fail.
            assertTrue(false);
        }
    }
}

