pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // The depositor account hard-coded in C
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    // Fuzz the deciding parameters: we fuzz the _timestamp and the batcherHash which the adversarial helper will
    // interpret to decide whether to revert. Keeping domain wide: timestamp any uint64, payload any bytes32.
    function testFuzz_property(uint64 _timestamp, bytes32 _batcherSeed) public {
        // Deploy a small helper whose address will be passed as batcherHash. The helper will revert when given
        // a specific seed-dependent pattern so we can create a scenario where some assignments (treated as
        // external interactions by the mutated contract) might revert; the fuzzer will explore _batcherSeed.
        RevertingBatcher helper = new RevertingBatcher(_batcherSeed);

        // Prepare arbitrary other parameters; we fuzz only timestamp and batcher-derived behavior.
        uint64 _number = uint64(1);
        uint256 _basefee = 1;
        bytes32 _hash = bytes32(0);
        uint64 _sequenceNumber = uint64(1);
        bytes32 _batcherHash = bytes32(uint256(uint160(address(helper))));
        uint256 _l1FeeOverhead = 0;
        uint256 _l1FeeScalar = 1;

        // Ensure caller is the depositor and has funds if needed (not required here but safe)
        vm.deal(DEPOSITOR, 1 ether);
        vm.prank(DEPOSITOR);

        // Call setL1BlockValues and observe whether it completes. We only assert when the call completes
        // successfully that timestamp equals the provided _timestamp. The reference C always satisfies this;
        // the mutant can be constructed to fail this property for some _batcherSeed-derived helper behavior.
        bool ok;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // Single assertion required: when call succeeded, contract.timestamp() == _timestamp
            assertTrue(c.timestamp() == _timestamp);
        }
    }
}

// Helper that will revert on a low-level call under a condition derived from the seed provided at deployment.
// The mutated contract could be sensitive to interacting with an address embedded in batcherHash; this
// helper simulates a callee that may revert for some batcherHash-derived addresses. The helper stores the
// seed and reverts in its fallback if calldata[0] equals seed's low byte (an arbitrary chosen trigger).
contract RevertingBatcher {
    bytes32 public seed;
    constructor(bytes32 _seed) payable {
        seed = _seed;
    }
    fallback() external payable {
        // Trigger revert for some calldata patterns based on seed to give the fuzzer a way to cause
        // a revert on one of the (mutated) later assignments while still allowing the call to complete in
        // the reference contract's ordering. We pick a simple rule: if msg.data length>0 and first byte equals seed[0], revert.
        if (msg.data.length > 0) {
            bytes1 first = msg.data[0];
            if (first == seed[0]) revert("revert-by-seed");
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive through public surface: attempt to setL1BlockValues from caller-supplied sender by using this contract as caller
    // We cannot change msg.sender here; the test caller of this function is the one attempting the call.
    // The function takes the values to set and the expected depositor address so we can express the property.

    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // read original basefee
        uint256 before = c.basefee();

        // attempt to set L1 block values from msg.sender (this contract). On P this should revert unless msg.sender == DEPOSITOR_ACCOUNT.
        // We perform the call and capture whether it succeeded using low-level call to avoid bubbling revert.
        bytes memory payload = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        (bool success, ) = address(c).call(payload);

        // read after
        uint256 after = c.basefee();

        // On the original contract P: if the call came from non-depositor (which is the typical case here),
        // the modifier requires revert and so the call must NOT have changed basefee. Thus after equals before.
        // On the mutant M where the require was removed, the call will succeed and basefee will equal the provided _basefee.

        assert(success == (after == _basefee) ? false : (after == before));
        // Explanation of the single assert above expressed as a single formula:
        // - If the contract allowed the change (success && after == _basefee) then the overall expression becomes false (violated on P).
        // - On P (require present) either the call reverted (success==false) and after==before -> RHS true, assert passes.
        // - On M the call succeeds and after==_basefee, making the ternary choose false which will fail the assert, distinguishing the mutant.
    }

    // fallback and receive to accept plain ether if ever needed (not used here but allowed)
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        // We must ensure the caller used for the external call is not the depositor account.
        // The depositor account in C is a known constant in the already-declared contract; we require the provided caller is different.
        require(caller != C(address(c)).DEPOSITOR_ACCOUNT(), "caller must not be depositor");
        // Make the call as `caller` by using a low-level call: construct calldata for setL1BlockValues and delegate the call through a proxy (this contract) using call with from simulated by msg.sender is not possible — instead we enforce the rule by observing revert when invoked by non-depositor via a direct external call from this contract only if this contract is not the depositor. To simulate a non-depositor caller, require this contract is not the depositor.
        require(address(this) != C(address(c)).DEPOSITOR_ACCOUNT(), "test contract must not be depositor");

        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller is not the depositor, the call must revert.
        // We express this over the inputs and the observed revert flag.
        assert(reverted == true);
    }
    receive() external payable { }
}

