        // The universal property: after any call, the stored basefee equals the provided _basefee.
        // This assertion is true for the reference contract for all inputs, and will fail on the mutant
        // that stores _basefee + 1 for some inputs (the fuzzer will find such an input).
        assertTrue(c.basefee() == _basefee);
    }
}
